let colors = ['#1160c6', '#fdd900', '#ef218f', '#3BD89F', '#81cfe5'];
let ctx;
let centerX, centerY;
let shapes = [];
let rects = [];

function setup() {
	createCanvas(900, 900);
	rectMode(CENTER);
	colorMode(HSB, 360, 100, 100, 100);
	ctx = drawingContext;
	centerX = width / 2;
	centerY = height / 2;
	initialize();
}

function draw() {
	background(0);
	fill('#fff');
	for (let r of rects) {
		square(r.x, r.y, r.w);
	}
	for (let s of shapes) {
		s.run();
	}


	if(frameCount % 260 == 0){
		initialize();
	}
}

function easeInOutExpo(x) {
	return x === 0
		? 0
		: x === 1
			? 1
			: x < 0.5 ? Math.pow(2, 20 * x - 10) / 2
				: (2 - Math.pow(2, -20 * x + 10)) / 2;
}

function initialize() {
	shapes = [];
	rects = [];

	let cellCount = 30;
	let gridArea = width * 0.7;
	let cellSize = gridArea / cellCount;
	let w = cellSize * 0.9;
	for (let j = 0; j < cellCount; j++) {
		for (let i = 0; i < cellCount; i++) {
			let x = i * cellSize + (cellSize / 2) + (width - gridArea) / 2;
			let y = j * cellSize + (cellSize / 2) + (height - gridArea) / 2;
			let dst = dist(x, y, centerX, centerY);
			let t = map(dst, 0, sqrt(sq(width / 2) + sq(height / 2)), 0, -120);
			if (random() < 0.5) {
				shapes.push(new Shape(x, y, w, w, t));
			} else {
				rects.push({ x: x, y: y, w: w });
			}
		}
	}
}

class Shape {
	constructor(x, y, w, h, timer) {
		this.x = x;
		this.y = y;
		this.w = w;
		this.h = h;
		this.scale = 0.002;
		this.startAngle = 40;
		this.targetAngle = 45;
		this.endAngle = 50;
		this.angle = this.startAngle
		this.offset = 0;
		this.maxOffset = (width / 5);

		this.timer = timer;
		this.t1 = 100;
		this.t2 = this.t1 + 0;
		this.t3 = this.t2 + 100;

		this.color1 = color('#ffffff');
		this.color2 = color(random(colors));
		this.currentColor = this.color1;
	}

	show() {
		let step = width / 400;
		noStroke();
		fill(this.currentColor);
		beginShape();
		for (let x = -this.w / 2; x <= this.w / 2; x += step) {
			let p = this.distortion(this.x + x, this.y - this.h / 2);
			vertex(p.x, p.y);
		}
		for (let y = -this.h / 2; y <= this.h / 2; y += step) {
			let p = this.distortion(this.x + this.w / 2, this.y + y);
			vertex(p.x, p.y);
		}
		for (let x = this.w / 2; x >= -this.w / 2; x -= step) {
			let p = this.distortion(this.x + x, this.y + this.h / 2);
			vertex(p.x, p.y);
		}
		for (let y = this.h / 2; y >= -this.h / 2; y -= step) {
			let p = this.distortion(this.x - this.w / 2, this.y + y);
			vertex(p.x, p.y);
		}
		endShape();
	}

	update() {
		this.timer++;
		if (0 < this.timer && this.timer < this.t1) {
			let nrm = norm(this.timer, 0, this.t1 - 1);
			this.angle = lerp(this.startAngle, this.targetAngle, nrm);
			this.offset = lerp(0, this.maxOffset, easeInOutExpo(nrm));
			this.currentColor = lerpColor(this.color1, this.color2, easeInOutExpo(nrm));
		}
		if (this.t2 < this.timer && this.timer < this.t3) {
			let nrm = norm(this.timer, this.t2, this.t3 - 1);
			this.angle = lerp(this.targetAngle, this.endAngle, nrm);
			this.offset = lerp(this.maxOffset, 0, easeInOutExpo(nrm));
			this.currentColor = lerpColor(this.color2, this.color1, easeInOutExpo(nrm));
		}
	}

	distortion(x, y) {
		let p = createVector(x, y);
		let ang = noise(p.x * this.scale, p.y * this.scale) * this.angle;
		let step = noise(p.x * this.scale, p.y * this.scale) * this.offset;
		p.x += cos(ang) * step;
		p.y += sin(ang) * step;
		return p;
	}

	run() {
		this.show();
		this.update();
	}
}

